NEW_IDS = ("net_basics", "net_ip", "net_subnetting", "net_ports", "net_devices", "net_troubleshoot", "net_wifi_protect", "net_osi_tcpip", "assistant_abilities")


PHOTOS = {"net_basics": "computer network cables switch", "net_ip": "network router ip address", "net_subnetting": "network switch server room", "net_ports": "ethernet ports network switch",
          "net_devices": "router switch network equipment", "net_troubleshoot": "network technician cables", "net_wifi_protect": "wifi router home", "net_osi_tcpip": "network cables data center",
          "assistant_abilities": "cybersecurity shield laptop"}


def _finish(raw):
    for e, _k in raw:
        if e["id"] in PHOTOS and not e.get("photo_query"):
            e["photo_query"] = PHOTOS[e["id"]]
    for e, kws in raw:
        if e["id"] in EXTRA_KW:
            kws.extend(fold(k) for k in EXTRA_KW[e["id"]].split("|") if k.strip())
    mine = set()
    for e, kws in raw:
        if e["id"] in NEW_IDS:
            mine.update(kws)
    for e, kws in raw:
        if e["id"] not in NEW_IDS:
            kws[:] = [k for k in kws if k not in mine or k in fold(EXTRA_KW.get(e["id"], "")).split("|")]


